package main

import (
	"os"
)

func main() {
	// Check if the log file exists and print its permissions
	info, err := os.Stat("logs.txt")
	if err != nil {
		if os.IsNotExist(err) {
			print("Log file does not exist.\n")
		} else {
			print("Error checking log file: ", err.Error(), "\n")
		}
	} else {
		print("Log file permissions: ", info.Mode().Perm(), "\n")
	}
}

